pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;
    function setUp() public { c = new NewIntelTechMedia(); }
    function testRegression_property() public {
        address owner = address(1);
        address alice = address(2);

        vm.deal(owner, 10000e18);

        vm.prank(owner);
        c = new NewIntelTechMedia();

        vm.prank(owner);
        c.finishDistribution();

        vm.deal(alice, 10000e18);
        vm.prank(alice);

        bool ok;
        try c.getTokens{value: 2500e18}() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false);
    }
}
